static uint32_t select_visible_page(unsigned int page)
{
  uint32_t visible_mask = 0;
  unsigned int index;

  for (index = 0; index < HOME_PAGE_COUNT; index++)
    {
      if (g_pages[index] == NULL)
        {
          continue;
        }

